40	// video frames (rgb24) every PSTEP frames, read sequentially from ffmpeg
41	function videoReader(file, every, pix = 'rgb24', start = 0) {
42	  // start (a multiple of every): accurate input seek half a frame before it, so the first decoded frame is frame `start`
43	  const w = 1920, h = 1080, size = w * h * (pix === 'gray' ? 1 : 3);
44	  const ss = start > 0 ? ['-ss', ((start - 0.5) / FPS).toFixed(6)] : [];
45	  // K4.4 (A41 a): a draft rendered at another size (540p at M5) is scaled to the 1920×1080 page frame the rules measure in; 1080p reads as before
46	  const vs = videoSize(file);
47	  if (!vs) throw new Error('ffprobe: no video size for ' + file);
48	  const up = vs === '1920x1080' ? '' : ',scale=1920:1080:flags=bicubic';
49	  const ff = spawn('ffmpeg', ['-v', 'error', ...ss, '-i', file, '-vf', `select='not(mod(n\\,${every}))'${up}`, '-vsync', '0', '-f', 'rawvideo', '-pix_fmt', pix, '-'], { stdio: ['ignore', 'pipe', 'inherit'] });
50	  let chunks = [], have = 0, done = false, waiters = [], idx = -1;
51	  ff.stdout.on('data', (c) => { chunks.push(c); have += c.length; ff.stdout.pause(); flush(); });
52	  ff.stdout.on('end', () => { done = true; flush(); });
53	  function flush() {
54	    while (waiters.length && (have >= size || done)) {
55	      if (have < size) { waiters.shift()(null); continue; }
56	      const all = Buffer.concat(chunks); const f = all.subarray(0, size);
57	      chunks = [all.subarray(size)]; have -= size;
58	      waiters.shift()(Buffer.from(f));
59	    }
60	    if (have < size * 2 && !done) ff.stdout.resume();
61	  }
62	  return {
63	    // frame number n (multiple of every)
64	    async get(n) {
65	      let f = null;
66	      while (idx < (n - start) / every) { f = await new Promise((res) => { waiters.push(res); flush(); }); idx++; if (!f) return null; }
67	      return f;
68	    },
