75	// zoom = scale) or the legacy form {t, pos, target, fovDeg, focusDist} (width of the frame at the focus plane). Same as checks/py/r_audio.camera_speed.
76	function cameraSpeed(cam) {
77	  const fr = cam.frames || [];
78	  const n = fr.length;
79	  const w = fr.map((f) => f.zoom !== undefined ? 1920 / f.zoom : 2 * (f.focusDist ?? 1) * Math.tan(((f.fovDeg ?? 40) * Math.PI / 180) / 2) * ((cam.fovAxis || 'vertical') === 'vertical' ? 16 / 9 : 1));
80	  const P = (f) => f.zoom !== undefined ? [[f.x, f.y, 0], [f.x, f.y, 0]] : [f.pos, f.target || f.pos];
